#include <array>
#include <iostream>
#include <stdexcept>
#include <string>

class Date {
public:
    static constexpr unsigned int monthsPerYear{12};
    explicit Date(int mn = 1, int dy = 1, int yr = 1900);
    Date(const Date& other);
    ~Date();
    void print() const;

private:
    unsigned int month{1};
    unsigned int day{1};
    unsigned int year{1900};
    unsigned int checkDay(int testDay) const;
};

Date::Date(int mn, int dy, int yr) {
    if (mn > 0 && mn <= static_cast<int>(monthsPerYear)) {
        month = static_cast<unsigned int>(mn);
    } else {
        throw std::invalid_argument("month must be 1-12");
    }
    year = static_cast<unsigned int>(yr);
    day = checkDay(dy);
    std::cout << "Date constructor: ";
    print();
    std::cout << "\n";
}

Date::Date(const Date& other)
    : month{other.month}, day{other.day}, year{other.year} {
    std::cout << "Date copy constructor: ";
    print();
    std::cout << "\n";
}

Date::~Date() {
    std::cout << "Date destructor: ";
    print();
    std::cout << "\n";
}

void Date::print() const {
    std::cout << month << '/' << day << '/' << year;
}

unsigned int Date::checkDay(int testDay) const {
    static const std::array<int, monthsPerYear + 1> daysPerMonth{
        0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31
    };

    if (testDay > 0 && testDay <= daysPerMonth[month]) {
        return static_cast<unsigned int>(testDay);
    }

    if (month == 2 && testDay == 29 &&
        (year % 400 == 0 || (year % 4 == 0 && year % 100 != 0))) {
        return static_cast<unsigned int>(testDay);
    }

    throw std::invalid_argument("Invalid day for current month and year");
}

class Employee {
public:
    Employee(const std::string& first, const std::string& last,
             const Date& dateOfBirth, const Date& dateOfHire);
    ~Employee();
    void print() const;

private:
    std::string firstName;
    std::string lastName;
    const Date birthDate;
    const Date hireDate;
};

Employee::Employee(const std::string& first, const std::string& last,
                   const Date& dateOfBirth, const Date& dateOfHire)
    : firstName{first},
      lastName{last},
      birthDate{dateOfBirth},
      hireDate{dateOfHire} {
    std::cout << "Employee constructor: " << firstName << ' ' << lastName << "\n";
}

Employee::~Employee() {
    std::cout << "Employee destructor: " << lastName << ", " << firstName << "\n";
}

void Employee::print() const {
    std::cout << lastName << ", " << firstName << "  Hired: ";
    hireDate.print();
    std::cout << "  Birthday: ";
    birthDate.print();
    std::cout << "\n";
}

int main() {
    Date birth{7, 24, 1949};
    Date hire{3, 12, 1988};
    std::cout << "---\n";
    Employee manager{"Bob", "Blue", birth, hire};
    std::cout << "---\n";
    manager.print();
    std::cout << "---\n";
    return 0;
}
